import{_ as r,o as i,c as n,ah as t}from"./chunks/framework.Bja9t6Wf.js";const c=JSON.parse('{"title":"Gerichtliche Nachspiele: Gernot Blümel & das Laptop-Mysterium","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/gericht-bluemel-laptop.md","filePath":"recherche/gericht-bluemel-laptop.md"}'),a={name:"recherche/gericht-bluemel-laptop.md"};function s(l,e,d,u,h,o){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="gerichtliche-nachspiele-gernot-blumel-das-laptop-mysterium" tabindex="-1">Gerichtliche Nachspiele: Gernot Blümel &amp; das Laptop-Mysterium <a class="header-anchor" href="#gerichtliche-nachspiele-gernot-blumel-das-laptop-mysterium" aria-label="Permalink to &quot;Gerichtliche Nachspiele: Gernot Blümel &amp; das Laptop-Mysterium&quot;">​</a></h1><p><strong>Vom Spaziergang mit dem Kinderwagen zur politischen Amnesie.</strong></p><p>Gernot Blümel, der ehemalige Finanzminister und engste Vertraute von Sebastian Kurz, lieferte 2021 eines der skurrilsten Kapitel der jüngeren österreichischen Polit-Geschichte. Seine „Laptop-Affäre“ ist in unserer Mockumentary das Paradebeispiel für die moderne Kunst der Datenvermeidung.</p><hr><h2 id="der-vorfall-februar-2021" tabindex="-1">Der Vorfall (Februar 2021) <a class="header-anchor" href="#der-vorfall-februar-2021" aria-label="Permalink to &quot;Der Vorfall (Februar 2021)&quot;">​</a></h2><p>Im Zuge der Ermittlungen zur Casinos-Affäre ordnete die WKStA eine Hausdurchsuchung bei Gernot Blümel an.</p><h3 id="die-highlights-der-absurditat" tabindex="-1">Die Highlights der Absurdität: <a class="header-anchor" href="#die-highlights-der-absurditat" aria-label="Permalink to &quot;Die Highlights der Absurdität:&quot;">​</a></h3><ul><li><strong>Der Spaziergang:</strong> Während die Beamten vor der Tür standen, verließ Blümels Lebensgefährtin mit dem gemeinsamen Kind und einem Kinderwagen das Haus.</li><li><strong>Der Fund:</strong> In dem Kinderwagen (oder bei der Partnerin, die Angaben variierten) befand sich Blümels privater Laptop.</li><li><strong>Die Rechtfertigung:</strong> Blümel gab an, der Laptop sei nur deshalb im Kinderwagen gelandet, damit die Partnerin ihn „nicht vergisst“. Kritiker werteten dies als den Versuch, Beweismittel vor der Sicherstellung zu retten.</li></ul><h2 id="die-„gedachtnislucken-im-u-ausschuss" tabindex="-1">Die „Gedächtnislücken“ im U-Ausschuss <a class="header-anchor" href="#die-„gedachtnislucken-im-u-ausschuss" aria-label="Permalink to &quot;Die „Gedächtnislücken“ im U-Ausschuss&quot;">​</a></h2><p>Unvergessen blieb Blümels Auftritt im Ibiza-Untersuchungsausschuss, bei dem er über <strong>80 Mal</strong> angab, sich an bestimmte Vorgänge, E-Mails oder Termine nicht erinnern zu können.</p><ul><li><strong>Zitat:</strong> „Ich habe keinen Laptop besessen.“ (Später korrigiert auf: Er habe ihn im Ministerium nicht genutzt).</li></ul><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>Blümel ist für unser Projekt der „Meister der Amnesie“.</p><ul><li><strong>Vom Archiv zum Kinderwagen:</strong> Während wir in der Horten-Ära die physische Vernichtung von Akten zeigen, zeigen wir in der Ära Blümel die „mobile Datensicherung“ und die mentale Auslöschung von Informationen.</li><li><strong>Pointillismus des Nichts:</strong> Die Summe seiner Erinnerungslücken ergibt am Ende ein vollständiges Bild der Verweigerung.</li></ul><hr><p><em>Quellen: Protokolle des Ibiza-Untersuchungsausschusses, Berichterstattung von Standard, Presse und ZIB2.</em></p>',17)])])}const g=r(a,[["render",s]]);export{c as __pageData,g as default};
